// Turn the webhook's bug_codes array (or comma-separated string) into one item per BugCode
const body = $('Webhook').first().json.body || {};
const codes = Array.isArray(body.bug_codes)
  ? body.bug_codes
  : String(body.bug_codes || '').split(',');
const seen = new Set();
const out = [];
for (const c of codes) {
  const code = String(c || '').trim();
  if (code && !seen.has(code)) {
    seen.add(code);
    out.push({ json: { BugCode: code } });
  }
}
if (!out.length) {
  throw new Error('bug_codes was provided but contained no valid bug codes.');
}
return out;

// Keep only bugs whose Close Build# matches the requested TR build
const body = $('Webhook').first().json.body || {};
const target = String(body.close_build || '').trim();
if (!target) {
  throw new Error('Request must include either bug_codes or close_build.');
}
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const b = item.json;
  const cb = String(b.CloseToBuild ?? b['Close Build#'] ?? '').trim();
  if (!cb) continue;
  // Lenient match: exact, or one contains the other (lets you pass just "185409")
  if (cb === target || cb.includes(target) || target.includes(cb)) {
    const code = String(b.BugCode || '').trim();
    if (code && !seen.has(code)) {
      seen.add(code);
      out.push({ json: { BugCode: code, CloseToBuild: cb } });
    }
  }
}
if (!out.length) {
  throw new Error('No closed bugs matched close_build "' + target + '" for ' + (body.product_name || 'the requested product') + ' in the last ' + (body.duration_months || 12) + ' months.');
}
return out;

// Group full bug details by product, parsing the eBug JSON-string fields
// (StatusLog / Comments / DetailData / UploadFile) into structured data so the
// downstream AI step gets clean root-cause / repro / verify text, not raw blobs.
const body = $('Webhook').first().json.body || {};

function parseJSONField(v) {
  if (v == null) return null;
  if (typeof v !== 'string') return v;
  try { return JSON.parse(v); } catch (e) { return null; }
}

const products = {};
const errors = [];
let count = 0;

for (const item of $input.all()) {
  const raw = item.json || {};
  // getOldeBug failures (e.g. flaky tsr API) arrive as an error item — record & skip
  if (raw.error && !raw.BugCode) {
    errors.push(String((raw.error && raw.error.message) || raw.error));
    continue;
  }
  // Unwrap common single-record wrappers
  let d = raw;
  for (const k of ['result', 'results', 'data', 'ebug', 'eBug']) {
    if (d && typeof d[k] === 'object' && d[k] !== null) d = d[k];
  }
  if (Array.isArray(d)) d = d[0] || {};

  const product = d.ProductName || d.productName || body.product_name || 'Unknown';

  const statusLog = parseJSONField(d.StatusLog) || [];
  const comments  = parseJSONField(d.Comments) || [];
  const detail    = parseJSONField(d.DetailData) || [];
  const uploads   = parseJSONField(d.UploadFile) || [];

  // Repro steps + locale coverage live inside DetailData field objects
  let reproSteps = null, osLanguage = null, priorityLabel = null, severityLabel = null;
  for (const f of (Array.isArray(detail) ? detail : [])) {
    const key = String(f.FieldCode || f.FieldName || '').toLowerCase();
    if (key.includes('describe')) reproSteps = f.FieldValue;
    else if (key.includes('os language')) osLanguage = f.FieldValue;
    else if (key === 'priority') priorityLabel = f.FieldValue;
    else if (key === 'severity') severityLabel = f.FieldValue;
  }

  // Resolutions = StatusLog entries that carry RD fix info (root cause / solution)
  const resolutions = (Array.isArray(statusLog) ? statusLog : [])
    .filter((s) => s && (s.RootCause || s.Solution))
    .map((s) => ({
      user: s.UserName || null,
      time: s.StatusTime || null,
      root_cause: s.RootCause || null,
      solution: s.Solution || null,
      risk: s.Risk || null,
      trace_url: s.TraceURL || null,
    }));

  const timeline = (Array.isArray(statusLog) ? statusLog : [])
    .map((s) => ({ status: s.Status || null, user: s.UserName || null, time: s.StatusTime || null }));

  const verifyComments = (Array.isArray(comments) ? comments : [])
    .map((c) => ({ user: c.UserName || null, time: c.CommentTime || null, comment: c.Comment || null }));

  const normalized = {
    BugCode: d.BugCode || raw.BugCode || '',
    ProductName: product,
    ParentTRCode: d.ParentTRCode || null,
    Status: d.Status !== undefined ? d.Status : null,
    Priority: d.EbugPriority !== undefined ? d.EbugPriority : (d.Priority !== undefined ? d.Priority : null),
    Severity: d.EbugSeverity !== undefined ? d.EbugSeverity : (d.Severity !== undefined ? d.Severity : null),
    PriorityLabel: priorityLabel,
    SeverityLabel: severityLabel,
    'Short Description': d.ShortDescription !== undefined ? d.ShortDescription : (d['Short Description'] !== undefined ? d['Short Description'] : null),
    ReproSteps: reproSteps,
    OSLanguage: osLanguage,
    ModuleOwner: d.BugBelong || d.IssueHandler || null,
    'Create Date': d.CreateTime !== undefined ? d.CreateTime : null,
    'Closed Date': d.CloseTime !== undefined ? d.CloseTime : null,
    'Build#': d.Build !== undefined ? d.Build : null,
    'Close Build#': d.CloseToBuild !== undefined ? d.CloseToBuild : null,
    Creator: d.Creator !== undefined ? d.Creator : null,
    Handler: d.MainHandler || d.Handler || null,
    Resolutions: resolutions,
    StatusTimeline: timeline,
    VerifyComments: verifyComments,
    AttachmentCount: Array.isArray(uploads) ? uploads.length : 0,
    raw: d,
  };

  if (!products[product]) products[product] = [];
  products[product].push(normalized);
  count++;
}

const allBugs = Object.values(products).reduce((a, b) => a.concat(b), []);
const trCodes = [...new Set(allBugs.map((b) => b.ParentTRCode).filter(Boolean))];

return [{
  json: {
    meta: {
      requested_product: body.product_name || null,
      close_build: body.close_build || null,
      bug_codes_supplied: Array.isArray(body.bug_codes) ? body.bug_codes.length : 0,
      fetched_at: $now.toISO(),
      bug_count: count,
      products: Object.keys(products),
      tr_codes: trCodes,
      errors: errors,
    },
    products: products,
  },
}];
